<?php
namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Http\Responses\ApiResponse; use App\Models\StaffAssignmentHistory; use App\Models\WeeklySupervisorAllocation; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class StaffAllocationController extends Controller { public function index(Request $request):JsonResponse{return ApiResponse::success(['assignment_history'=>StaffAssignmentHistory::with(['person','department','trainingSite'])->latest('start_date')->get(),'weekly_allocations'=>WeeklySupervisorAllocation::with(['person','department'])->when(!$request->boolean('show_archived'), fn($q)=>$q->whereNull('archived_at'))->when($request->query('academic_year'), fn($q, $y)=>$q->where('academic_year', $y))->when($request->query('week_number'), fn($q, $w)=>$q->where('week_number', $w))->when($request->query('department_id'), fn($q, $d)=>$q->where('department_id', $d))->orderBy('week_number')->get()]);} public function storeAllocation(Request $r):JsonResponse{$d=$r->validate(['academic_year'=>['required','string'],'week_number'=>['required','integer','min:1'],'department_id'=>['nullable','exists:departments,id'],'person_id'=>['nullable','exists:people,id'],'supervisor_name'=>['nullable','string'],'subgroup'=>['nullable','string'],'student_count'=>['nullable','integer','min:0'],'notes'=>['nullable','string']]);return ApiResponse::success(WeeklySupervisorAllocation::create($d),'Allocation created.',[],201);} public function updateAllocation(Request $r, WeeklySupervisorAllocation $allocation):JsonResponse{$allocation->update($r->validate(['academic_year'=>['sometimes','string'],'week_number'=>['sometimes','integer','min:1'],'department_id'=>['nullable','exists:departments,id'],'person_id'=>['nullable','exists:people,id'],'supervisor_name'=>['nullable','string'],'subgroup'=>['nullable','string'],'student_count'=>['nullable','integer','min:0'],'notes'=>['nullable','string']]));return ApiResponse::success($allocation->fresh());} public function archiveAllocation(WeeklySupervisorAllocation $allocation):JsonResponse{$allocation->update(['archived_at'=>now()]);return ApiResponse::success($allocation->fresh(),'Record archived.');} }
